sys_ui_action.client_script_v2:
function onClick(g_form, g_list) {
    var syncFilterSysId = '';

    // Determine context: form or list
    if (typeof g_form !== 'undefined' && g_form && g_form.getUniqueValue) {
        // Form context
        syncFilterSysId = g_form.getUniqueValue();
    } else if (typeof g_list !== 'undefined' && g_list) {
        // List context - get selected row's sys_id
        var selectedRows = g_list.getChecked();
        if (selectedRows) {
            syncFilterSysId = selectedRows.split(',')[0];
        }
    }

    // Fallback: try to get from URL or global variable
    if (!syncFilterSysId && typeof gel !== 'undefined' && gel('sys_uniqueValue')) {
        syncFilterSysId = gel('sys_uniqueValue').value;
    }

    if (!syncFilterSysId) {
        alert('Unable to determine Sync Filter. Please select a record.');
        return false;
    }

    // Open the UI Page in a GlideDialogWindow
    var dialog = new GlideDialogWindow('illumio_sync_filter_matching_workloads');
    dialog.setTitle('Matching Workloads');
    dialog.setPreference('sysparm_sync_filter_id', syncFilterSysId);
    dialog.setSize(700, 600);
    dialog.render();

    return false;
}

sys_ui_action.script:
(function executeShowMatchingWorkloads(current, action, gs) {
      var syncFilterSysId = current.getUniqueValue();
      if (gs.nil(syncFilterSysId)) {  
          gs.addErrorMessage("Unable to determine Sync Filter.");
          action.setRedirectURL(current);
          return;
      }                                                                        

      var utils = new IllumioUtils();
      var result = utils.getWorkloadsBySyncFilter(syncFilterSysId, true); // skipActiveCheck for preview

      if (!result.success) {
          gs.addErrorMessage("Error: " + result.message);                                                                    
          action.setRedirectURL(current);                   
          return;
      }

      if (result.workloads.length === 0) {
          gs.addInfoMessage("No workloads match the current filter criteria.");
          action.setRedirectURL(current);          
          return;
      }

      // Collect sys_ids                    
      var workloadIds = [];
      for (var i = 0; i < result.workloads.length; i++) {
          workloadIds.push(result.workloads[i].sys_id);     
      }

      // Redirect to filtered workloads list
      action.setRedirectURL("x_illu2_illumio_illumio_pce_workload_list.do?sysparm_query=sys_idIN" + workloadIds.join(","));
  })(current, action, gs);
